 readonly Dictionary<ushort,byte> statusRoutesFG83=new Dictionary<ushort,byte>();readonly Dictionary<ushort,string> statusBodiesFG83=new Dictionary<ushort,string>();
 void StatusItemFG83(byte[] body,ushort sequence){string fingerprint=Convert.ToBase64String(body),prior;byte route;if(statusBodiesFG83.TryGetValue(sequence,out prior)){if(prior!=fingerprint)throw new InvalidDataException("Status item sequence reused across item types");route=statusRoutesFG83[sequence];}else{route=0;ushort slot;try{slot=Offline70EconomyProtocol.SkillBookSlot(body,keys);Sync();Offline70EconomyEntry item=Offline70Economy.Find(assets,0,slot);if(item!=null)route=(byte)(item.ItemId==3?1:item.ItemId==2682275?2:item.ItemId==1204||item.ItemId==1205?3:0);}catch(InvalidDataException){}statusBodiesFG83.Add(sequence,fingerprint);statusRoutesFG83.Add(sequence,route);}if(route==1){if(!UseLetheFG83(body,sequence))throw new InvalidDataException("Lethe routing changed");}else if(route==2){if(!UseQpResetItem(body,sequence))throw new InvalidDataException("QP item routing changed");}else if(route==3){if(!UseTpBookFG214(body,sequence))throw new InvalidDataException("TP book routing changed");}else UseSkillBook(body,sequence);}
 // TP+1技能书 (1204) and TP+5技能书 (1205): the wallet is BonusTp, the page-0 特性技能点
 // remainder op19 reports in its closing sfp(2) short. Two ORIG paths grant it: the quest-clear
 // reward scan (CSkillChanger::_addSFPRelatedItem 0x0860a918) folds the book into points without
 // ever adding it, and the direct op32 use lands in CUser::increase_status, whose 0x4b4/0x4b5
 // cases are `type=0x11, value=1/5` — SFP, never SP. The reply must carry that 0x11 or the client
 // labels the gain as SP (the 1205 use once showed "SP +5").
 // ORIG stops there: the case body sends the 12-byte reply and returns — no send_skill_info. Our
 // extra op19 refresh is what the client answers by tearing down its open skill window, so it is
 // gone; the client credits the SFP wallet itself from the reply. The CN70 client has no native
 // "TP +n" line (type 0 is the only one with a popup), so the gain is also announced through the
 // op12 system line (uid = receiving role, same body as make_packet_chat_msg type 0).
 readonly Dictionary<ushort,string> tpBookRequestsFG214=new Dictionary<ushort,string>();readonly Dictionary<ushort,byte[]> tpBookRepliesFG214=new Dictionary<ushort,byte[]>();
 bool UseTpBookFG214(byte[] body,ushort sequence){string fingerprint=Convert.ToBase64String(body),prior;if(tpBookRequestsFG214.TryGetValue(sequence,out prior)){if(prior!=fingerprint)throw new InvalidDataException("TP book sequence reused");Send("tp-book-repeat32",tpBookRepliesFG214[sequence]);return true;}ushort slot=0,amount=0;bool success=false;Dictionary<ushort,uint> collection=null;try{if(dungeon.Active)throw new InvalidDataException("TP book requires town");slot=Offline70EconomyProtocol.SkillBookSlot(body,keys);Sync();collection=CollectionSnapshot();Offline70EconomyEntry owned=Offline70Economy.Find(assets,0,slot);if(owned==null)throw new InvalidDataException("TP book ownership");if(owned.ItemId!=1204&&owned.ItemId!=1205)throw new InvalidDataException("TP book item");amount=Offline70Economy.TpBookAmount(owned.ItemId);Offline70EconomyItemDefinition d=Offline70Economy.Definition(owned.ItemId);if(role.Level<d.MinimumLevel)throw new InvalidDataException("TP book level");bool duplicate;assets=Offline70Economy.Apply(economyPath,session+"-tp-book-"+sequence,"tp-book",slot+":"+owned.ItemId+":"+amount,delegate(Offline70EconomyState s){Offline70EconomyEntry book=Offline70Economy.Find(s,0,slot);if(book==null||book.ItemId!=owned.ItemId||s.BonusTp>10000-amount)throw new InvalidDataException("TP book ownership or TP capacity");s.BonusTp=checked((ushort)(s.BonusTp+amount));if(book.Quantity==1)s.Inventory.Remove(book);else book.Quantity--;},out duplicate);success=true;Note("TP_BOOK_COMMITTED item="+owned.ItemId+" grantTp="+amount+" bonusTp="+assets.BonusTp+" duplicate="+duplicate);}catch(InvalidDataException e){Note("TP_BOOK_REJECTED "+e.Message);}byte[] reply=Offline70EconomyProtocol.SkillBookReply(slot,amount,0x11,success,keys);tpBookRequestsFG214.Add(sequence,fingerprint);tpBookRepliesFG214.Add(sequence,reply);Send(success?"tp-book-used32":"tp-book-failed32",reply);if(success){Send("tp-book-notice",Offline70RoleProtocol.BatchPacketFG(0,12,Offline70TowerDialogFG363.Body(role.Id,"TP +"+amount+"（当前剩余 TP "+assets.BonusTp+"）"),keys,false));Note("TP_BOOK_NOTICE grant="+amount+" remaining="+assets.BonusTp);CollectionChanged(collection);}return true;}
 readonly Dictionary<ushort,string> resetRequestsFG83=new Dictionary<ushort,string>();readonly Dictionary<ushort,byte[]> resetRepliesFG83=new Dictionary<ushort,byte[]>();
 void ResetRefreshFG83(){Sync();skills=ActiveSkillsFG129();Send("lethe-current-skills19",SkillsReplyFG129());Send("lethe-current-items",Offline70EconomyProtocol.InventoryRestoreReply(assets,keys));}
 bool UseLetheFG83(byte[] body,ushort sequence){string fingerprint=Convert.ToBase64String(body),prior;if(resetRequestsFG83.TryGetValue(sequence,out prior)){if(prior!=fingerprint)throw new InvalidDataException("Lethe request sequence reused");Send("lethe-repeat32",resetRepliesFG83[sequence]);ResetRefreshFG83();return true;}ushort slot;try{slot=Offline70EconomyProtocol.SkillBookSlot(body,keys);}catch(InvalidDataException){return false;}Sync();Offline70EconomyEntry item=Offline70Economy.Find(assets,0,slot);if(item==null||item.ItemId!=3)return false;bool success=false;Dictionary<ushort,uint> collection=CollectionSnapshot();try{if(dungeon.Active)throw new InvalidDataException("Lethe bottle requires town");bool duplicate;if(assets.ActiveStyleFG129==0)assets=Offline70SkillResetFG83.Use(economyPath,skillPath,session+"-lethe-"+sequence,slot,out duplicate);else assets=Offline70Economy.Apply(economyPath,session+"-lethe-"+sequence,"style-reset",slot.ToString(),delegate(Offline70EconomyState s){Offline70EconomyEntry bottle=Offline70Economy.Find(s,0,slot);if(bottle==null||bottle.ItemId!=3||s.SecondSkillsFG129.SpentSp==0)throw new InvalidDataException("Second page refundable SP or Lethe ownership");s.SecondSkillsFG129=Offline70SkillSlots.ResetPlanFG83(s.SecondSkillsFG129,session+"-lethe-"+sequence);if(bottle.Quantity==1)s.Inventory.Remove(bottle);else bottle.Quantity--;},out duplicate);skills=ActiveSkillsFG129();skillResetEpochFG83++;success=true;Note("LETHE_COMMITTED bank="+assets.ActiveStyleFG129+" refund="+(assets.ActiveStyleFG129==0?assets.SkillResetFG83.ReturnedSp:0)+" remainingSp="+RemainingSp()+" duplicate="+duplicate);}catch(InvalidDataException e){Note("LETHE_REJECTED "+e.Message);}byte[] reply=Offline70SkillResetFG83.Reply(slot,success,keys);resetRequestsFG83.Add(sequence,fingerprint);resetRepliesFG83.Add(sequence,reply);Send(success?"lethe-used32":"lethe-failed32",reply);if(success){ResetRefreshFG83();CollectionChanged(collection);}return true;}
}
